// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(newOwner != address(0));

        // actor initializes and thereby becomes the owner
        vm.prank(actor);
        c.initialize();
        require(c.owner() == actor, "setup: owner mismatch");

        // the owner transfers ownership to newOwner
        vm.prank(actor);
        c.transferOwnership(newOwner);

        // Rule: for any admissible input, ownership is transferred to newOwner.
        // The mutant sets owner to the caller instead, so it fails whenever newOwner != actor.
        assertTrue(c.owner() == newOwner, "ownership must be transferred to newOwner");
    }
}
